<template><div class="form-page"><el-form label-width="180px" label-position="left"><MetadataEditor :model="localForm" title="基础配置" /><el-card shadow="never"><template #header>ServiceAccount 配置</template><el-form-item label="自动挂载服务账号令牌"><el-switch v-model="localForm.automountServiceAccountToken" /></el-form-item><ArrayEditor v-model="localForm.imagePullSecrets" title="镜像拉取密钥" label-key="name" :create-item="createName"><template #default="{ item }"><el-form-item label="名称"><el-input v-model="item.name" /></el-form-item></template></ArrayEditor><ArrayEditor v-model="localForm.secrets" title="挂载密钥" label-key="name" :create-item="createName"><template #default="{ item }"><el-form-item label="名称"><el-input v-model="item.name" /></el-form-item></template></ArrayEditor></el-card></el-form></div></template><script setup lang="ts">import { computed } from 'vue'; import type { ServiceAccountFormData } from '@/types/k8s'; import MetadataEditor from '@/components/common/MetadataEditor.vue'; import ArrayEditor from '@/components/common/ArrayEditor.vue'; const props = defineProps<{ modelValue: ServiceAccountFormData }>(); const emit = defineEmits<{ 'update:modelValue':[value:ServiceAccountFormData] }>(); const localForm = computed({ get:()=>props.modelValue, set:(value:ServiceAccountFormData)=>emit('update:modelValue', value) }); const createName = ()=>({ name:'' });</script><style scoped>.form-page{display:grid;gap:16px}</style>
